const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const isDemo = location.pathname.startsWith('/demo');
const api = isDemo ? '/demo/api' : '/api';
const webRoot = isDemo ? '/demo' : '';
const urlParams=new URLSearchParams(location.search);
const reviewPreview=urlParams.get('readOnlyPreview')==='1'||urlParams.get('reviewPreview')==='before';
const reviewCandidate=urlParams.get('reviewPreview')!=='before';
mountWorkspaceHeader();
let panels;
const uuid = () => crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`;
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const state = { data:null, view:'board', courseId:null, weekId:null, cardId:null, selection:'', drafts:{}, quizDrafts:{}, readingPositions:{}, boardPositions:{}, pan:{x:24,y:20,z:1}, quiz:null, asset:null, polling:new Map(), saveTimer:null, chatLoad:0, railObserver:null, resumedJobs:new Set() };

async function request(path, options = {}) {
  const headers = { ...(options.body ? {'Content-Type':'application/json','X-Study-Client':'study-room'} : {}), ...(options.headers || {}) };
  let response;
  try { response = await fetch(`${api}${path}`, {...options, headers}); }
  catch { throw new Error('서버에 연결하지 못했습니다. 읽던 내용은 화면에 남아 있습니다.'); }
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || '요청을 처리하지 못했습니다.');
  return body;
}
function activeUrl(url){return String(url||'').replace(/^\/api(?=\/|$)/,api);}
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(el.timer); el.timer=setTimeout(()=>el.classList.remove('show'),3800); }
function card(id = state.cardId) { return state.data?.cards?.find(x=>x.id===id); }
function course(id = state.courseId) { return state.data?.courses?.find(x=>x.id===id); }
function week(id = state.weekId) { return course()?.weeks?.find(x=>x.id===id); }
function scopedCards() { const cards=(state.data?.cards || []).filter(x => x.courseId===state.courseId), weeks=course()?.weeks||[], original=new Map(cards.map((item,index)=>[item.id,index])), weekRank=id=>{const n=weeks.findIndex(w=>w.id===id);return n<0?Number.MAX_SAFE_INTEGER:n;}, cardRank=item=>{const ids=weeks.find(w=>w.id===item.weekId)?.cardIds||[], n=ids.indexOf(item.id);return n<0?(original.get(item.id)??Number.MAX_SAFE_INTEGER):n;}; return cards.slice().sort((a,b)=>weekRank(a.weekId)-weekRank(b.weekId)||cardRank(a)-cardRank(b)||String(a.title).localeCompare(String(b.title),'ko')); }
function scopeText() { return course()?displayCourseTitle(course()):'학습 범위'; }
async function refreshCatalog(){invalidateAdminSnapshot();try{const fresh=await request('/bootstrap');state.data={...state.data,courses:fresh.courses,cards:fresh.cards,status:fresh.status};setConnection(fresh.status);}catch(e){showError(e);}}
function scopeKey(){return `${state.courseId || ''}/${state.weekId || ''}`;}
function saveUi() {
  const key=scopeKey();
  if(state.view==='review'&&$('#reading')?.dataset.loading!=='true')state.readingPositions[key]=$('#reading').scrollTop;
  state.boardPositions[key]={...state.pan};
  if(reviewPreview)return;
  clearTimeout(state.saveTimer);
  state.saveTimer=setTimeout(async()=>{try{await request('/ui',{method:'PUT',body:JSON.stringify({view:state.view,courseId:state.courseId,weekId:null,cardId:state.cardId,board:state.pan,reading:state.readingPositions[scopeKey()]||0,readingPositions:state.readingPositions,boardPositions:state.boardPositions,drafts:state.drafts,quizDrafts:state.quizDrafts,noteDrafts:state.noteDrafts||{}})});}catch{toast('화면 위치를 저장하지 못했습니다.');}},500);
}
function setConnection(status) { const el=$('#connection'); el.hidden=true; el.textContent=''; }

function svg(figure={}) { const type=figure.type || 'none', label=esc(figure.caption || '개념 그림');
  if(type==='none') return '';
  const base=(body)=>`<svg viewBox="0 0 300 128" role="img" aria-label="${label}">${body}</svg>`;
  const node=(x,y,t,fill='#d9ebe3')=>`<circle cx="${x}" cy="${y}" r="13" fill="${fill}" stroke="#29635a"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="10" fill="#243a31">${t}</text>`;
  if(type==='xor') return base(`<path d="M28 98V16M28 98H278" stroke="#819087"/><path d="M43 84L242 25" stroke="#b6c3bd" stroke-dasharray="4 3"/><circle cx="62" cy="81" r="6" fill="#29635a"/><circle cx="62" cy="36" r="6" fill="#c36b58"/><circle cx="228" cy="81" r="6" fill="#c36b58"/><circle cx="228" cy="36" r="6" fill="#29635a"/><text x="52" y="107" font-size="10">0,0</text><text x="214" y="107" font-size="10">1,0</text><text x="34" y="30" font-size="10">0,1</text><text x="220" y="30" font-size="10">1,1</text><text x="150" y="16" text-anchor="middle" font-size="11" fill="#53645c">XOR: 한 직선으로 분리할 수 없음</text>`);
  if(type==='bias') return base(`<text x="28" y="27" font-size="12">Σwᵢxᵢ − θ</text><path d="M95 22h38" stroke="#29635a"/><path d="m127 17 9 5-9 5" fill="#29635a"/><text x="147" y="27" font-size="12">Σwᵢxᵢ + b</text><text x="151" y="48" font-size="10" fill="#53645c">b = −θ</text><path d="M22 83h67M22 83v-25" stroke="#82918a"/>${node(43,73,'x₁')}${node(77,73,'x₂')}<rect x="110" y="57" width="54" height="33" rx="5" fill="#d9ebe3"/><text x="137" y="78" text-anchor="middle" font-size="10">Σ</text>${node(43,101,'+1','#f2e8d9')}<path d="M56 96 110 84" stroke="#29635a"/><text x="68" y="106" font-size="10">b</text><text x="188" y="78" font-size="12">또는 −1 × θ</text>`);
  if(type==='layers') return base(`${[48,150,252].map((x,i)=>[38,64,90].map(y=>node(x,y,i===1?'h':'')).join('')).join('')}<path d="M62 38 136 38M62 38 136 64M62 64 136 64M62 90 136 90M164 38 238 38M164 64 238 64M164 90 238 90" stroke="#8ca39a"/><text x="48" y="20" text-anchor="middle" font-size="10">input</text><text x="150" y="20" text-anchor="middle" font-size="10">hidden</text><text x="252" y="20" text-anchor="middle" font-size="10">output</text>`);
  if(type==='outputs') return base(`<rect x="18" y="34" width="69" height="48" rx="6" fill="#d9ebe3"/><text x="52" y="54" text-anchor="middle" font-size="10">feature</text><text x="52" y="69" text-anchor="middle" font-size="10">F개</text><path d="M89 58h42" stroke="#29635a"/><path d="m126 53 9 5-9 5" fill="#29635a"/><rect x="139" y="23" width="55" height="22" rx="4" fill="#e9f2ee"/><rect x="139" y="53" width="55" height="22" rx="4" fill="#e9f2ee"/><rect x="139" y="83" width="55" height="22" rx="4" fill="#e9f2ee"/><text x="166" y="38" text-anchor="middle" font-size="10">1 · linear</text><text x="166" y="68" text-anchor="middle" font-size="10">1 · sigmoid</text><text x="166" y="98" text-anchor="middle" font-size="10">K · softmax</text><text x="229" y="38" font-size="10">회귀</text><text x="229" y="68" font-size="10">이진</text><text x="229" y="98" font-size="10">K-class</text>`);
  if(type==='loss') return base(`<path d="M29 100V18M29 100H281" stroke="#82918a"/><path d="M48 31C70 54 92 69 125 80S202 92 264 96" fill="none" stroke="#29635a" stroke-width="3"/><text x="37" y="17" font-size="10">loss</text><text x="222" y="112" font-size="10">정답 class 확률</text><circle cx="189" cy="91" r="4" fill="#c36b58"/><text x="196" y="84" font-size="10">확률 ↑, loss ↓</text>`);
  if(type==='neuron') return base(`${node(35,38,'x₁')}${node(35,73,'x₂')}${node(35,105,'xₙ')}<path d="M49 38 126 57M49 73 126 63M49 105 126 69" stroke="#829e94"/><rect x="126" y="45" width="55" height="35" rx="17" fill="#d9ebe3"/><text x="153" y="67" text-anchor="middle" font-size="10">Σ + f</text><path d="M181 62h50" stroke="#29635a"/><path d="m226 57 9 5-9 5" fill="#29635a"/><text x="238" y="66" font-size="12">o</text><text x="85" y="31" font-size="10">weight</text>`);
  return base(`<text x="150" y="63" text-anchor="middle" font-size="12">${label}</text>`);
}
function currentWeekForCourse(c) { return c.weeks?.find(w=>w.id===state.weekId) || c.weeks?.[0]; }
function choose(courseId, _weekId) { saveUi(); state.courseId=courseId; state.weekId=null; state.cardId=scopedCards()[0]?.id || null; state.selection=''; state.pan=state.boardPositions[scopeKey()] || {x:24,y:20,z:1}; render(); saveUi(); }
function displayCourseTitle(c){return isDemo?String(c.title||'').replace(/\s*—\s*합성 데모\s*$/,''):c.title;}
function weekLabel(w={}){const raw=String(w.title||'').replace(/^\s*\d+\s*주차\s*\d+\s*강\s*[··-]?\s*/,'').trim();if(w.weekNumber)return `${w.weekNumber}주차${w.lessonNumber?` ${w.lessonNumber}강`:''}${raw?` · ${raw}`:''}`;return w.title||'수업';}
function quizScopeChoices(weeks,scopeKind){return scopeKind==='week'?[...new Map(weeks.map(w=>[String(w.weekNumber),w])).values()]:weeks;}
function quizPreviewLabel(weeks,scopeKind,selectedWeek){if(scopeKind==='course')return '전체 수업';if(scopeKind==='week'){const count=weeks.filter(w=>Number(w.weekNumber)===Number(selectedWeek?.weekNumber)).length;return `${selectedWeek?.weekNumber||''}주차${count?` · ${count}개 수업`:''}`.trim();}return weekLabel(selectedWeek);}
function renderSidebar(){const side=$('#sidebar'),courses=state.data?.courses||[];if(!courses.length){side.innerHTML='<div id="reviewOutline"><p class="outline-label">과목</p><button class="sidebar-add" id="sidebarCourseManager">과목 추가</button></div>';$('#sidebarCourseManager').onclick=()=>openCourseManager({state,request,uuid,bootstrap,toast});return;}
 side.innerHTML=`<div id="reviewOutline"><p class="outline-label">과목 <span class="course-switch"><button class="quiet" id="coursePrev" aria-label="이전 과목">‹</button><button class="quiet" id="courseNext" aria-label="다음 과목">›</button></span></p><div class="review-courses">${courses.map(c=>`<button class="course-button ${c.id===state.courseId?'selected':''}" data-course="${esc(c.id)}">${esc(displayCourseTitle(c))}</button>`).join('')}</div><p class="outline-label">모든 주차</p>${(course()?.weeks||[]).map(w=>state.view==='review'?`<details class="week-outline" data-week-toggle="${esc(w.id)}"><summary>${esc(weekLabel(w))}</summary><div>${scopedCards().filter(c=>c.weekId===w.id).map(c=>`<button class="outline-button" data-jump="${esc(c.id)}">${esc(c.title)}</button>`).join('')||'<span class="muted">아직 준비된 개념이 없습니다.</span>'}</div></details>`:`<button class="week-link" data-week="${esc(w.id)}">${esc(weekLabel(w))}</button>`).join('')}<button class="sidebar-add" id="sidebarCourseManager">과목 관리</button></div>`;
 const move=delta=>{const i=Math.max(0,courses.findIndex(c=>c.id===state.courseId));choose(courses[(i+delta+courses.length)%courses.length].id,null);};$('#coursePrev').onclick=()=>move(-1);$('#courseNext').onclick=()=>move(1);
 $$('[data-course]',side).forEach(b=>b.onclick=()=>choose(b.dataset.course,null));$('#sidebarCourseManager').onclick=()=>openCourseManager({state,request,uuid,bootstrap,toast});
 $$('[data-jump]',side).forEach(b=>b.onclick=()=>jumpTo(b.dataset.jump));$$('[data-week]',side).forEach(b=>b.onclick=()=>{const target=state.view==='board'?$(`[data-board-week="${CSS.escape(b.dataset.week)}"]`):state.view==='materials'?$(`[data-material-week="${CSS.escape(b.dataset.week)}"]`):null;if(target)target.scrollIntoView({block:'start',behavior:'smooth'});else{state.cardId=scopedCards().find(c=>c.weekId===b.dataset.week)?.id;setView('review');setTimeout(()=>jumpTo(state.cardId),250);}});
}
function cardFigure(){return '';}

function renderBoard() { $('#boardScope').textContent=scopeText(); const groups=[]; for(const c of scopedCards()){ let g=groups.find(x=>x.key===`${c.courseId}/${c.weekId}`); if(!g){g={key:`${c.courseId}/${c.weekId}`, title:displayCourseTitle(course(c.courseId))+' · '+course(c.courseId)?.weeks.find(w=>w.id===c.weekId)?.title,cards:[]};groups.push(g);} g.cards.push(c); }
  $('#boardWorld').innerHTML=groups.map(g=>`<section class="board-group" data-board-week="${esc(g.cards[0].weekId)}"><h2>${esc(g.title)}</h2><div class="card-grid">${g.cards.map(c=>`<button class="card" data-card="${esc(c.id)}">${cardFigure(c)?`<div class="card-figure">${cardFigure(c)}</div>`:''}<div class="card-body"><h3>${esc(c.title)}</h3><p>${inlineMarkdown(c.core)}</p><span style="display:inline-block;margin-top:9px;padding:2px 7px;border:1px solid #dfe4e1;border-radius:12px;color:#5f6b65;font-size:11px">${esc(c.state?.label || '확인 전')} · ${esc(c.state?.confirmed ?? 0)}/${esc(c.state?.total ?? c.requirements?.filter(r=>r.required!==false).length ?? 0)}</span></div></button>`).join('')}</div></section>`).join('') || '<p>이 범위에는 아직 읽을 카드가 없습니다.</p>';
  $$('[data-card]').forEach(b=>b.onclick=()=>openCard(b.dataset.card)); applyTransform();
}
function applyTransform(){ if(reviewCandidate){$('#boardWorld').style.transform='none';return;} $('#boardWorld').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.pan.z})`; $('#zoomLabel').value=`${Math.round(state.pan.z*100)}%`; saveUi(); }
function fitBoard(){if(reviewCandidate){$('#boardWorld').style.transform='none';return;} const wrap=$('#boardWrap'), world=$('#boardWorld'); if(!world.offsetWidth) return; state.pan.z=Math.max(.38,Math.min(1,(wrap.clientWidth-46)/world.offsetWidth,(wrap.clientHeight-40)/world.offsetHeight)); state.pan.x=Math.max(16,(wrap.clientWidth-world.offsetWidth*state.pan.z)/2); state.pan.y=16; applyTransform(); }
function openCard(id) { const c=card(id); state.cardId=id; $('#dialog').innerHTML=`<button class="quiet close" aria-label="닫기">×</button><h2>${esc(c.title)}</h2><p class="muted">${esc(c.goal)}</p>${cardFigure(c)?`<div class="figure">${cardFigure(c)}</div>`:''}<p>${inlineMarkdown(c.core)}</p>${c.details.map(d=>`<p><strong>${esc(d.title)}</strong><br>${inlineMarkdown(d.text)}</p>`).join('')}<div class="dialog-actions"><button data-edit="${esc(id)}">직접 고치기</button><button class="primary" id="readCard">문서에서 읽기</button></div>`; const d=$('#dialog'); d.showModal(); $('.close',d).onclick=()=>d.close(); $('[data-edit]',d).onclick=()=>editCard(id); $('#readCard',d).onclick=()=>{d.close();setView('review');setTimeout(()=>jumpTo(id),10);}; }
function lessonMarkup(c){return `<section class="lesson" id="lesson-${esc(c.id)}" data-card="${esc(c.id)}"><h2>${esc(c.title)}</h2><p class="goal">${esc(c.goal)}</p>${c.figure?.type!=='none'?`<div class="figure">${svg(c.figure)}${c.figure?.caption?`<p class="figure-caption">${esc(c.figure.caption)}</p>`:''}</div>`:''}<p class="selectable">${inlineMarkdown(c.core)}</p>${c.details.map(d=>`<h3 class="detail-title">${esc(d.title)}</h3><p class="selectable">${inlineMarkdown(d.text)}</p>`).join('')}<div class="lesson-actions"><button class="quiet" data-ask="${esc(c.id)}">이 부분에 질문</button><button class="quiet" data-source="${esc(c.id)}">출처·기록</button><button class="quiet" data-edit="${esc(c.id)}">수정</button></div></section>`;}
function bindLessonActions(root=document){ $$('[data-ask]',root).forEach(b=>b.onclick=()=>{const oldWeek=chatWeek();state.cardId=b.dataset.ask;state.selection='';if(reviewCandidate&&oldWeek!==chatWeek())restoreChat(); renderChatContext();openChat();$('#chatInput').focus();}); $$('[data-source]',root).forEach(b=>b.onclick=()=>showHistory(b.dataset.source)); $$('[data-edit]',root).forEach(b=>b.onclick=()=>editCard(b.dataset.edit)); }
function readingWeekHeader(w){return `<section class="week-reading-header" data-week-header="${esc(w.id)}"><p class="eyebrow">${esc(w.title)}</p>${w.overview?`<p class="intro">${esc(w.overview)}</p>`:''}${w.preview?`<details class="preview"><summary>이 주차에서 어떤 문제를 풀게 되나요?</summary><p>${esc(w.preview.prompt)}</p>${w.preview.solution?`<button class="quiet small" data-preview-week="${esc(w.id)}">대표 풀이 보기</button>`:''}</details>`:''}</section>`;}
function renderReview(){ if(reviewCandidate)return mountReview({$,esc,state,cards:scopedCards(),course:course(),api,lessonMarkup,bindLessonActions,restoreChat,displayCourseTitle,choose,jumpTo,renderChatContext,setView,showTextDialog,saveUi,exposure,request,uuid,toast}).catch(showError); const c=course(), cards=scopedCards(), weeks=c?.weeks||[]; $('#reviewScope').textContent=scopeText(); if(!state.cardId) state.cardId=cards[0]?.id; let currentWeek=''; const body=cards.map(item=>{let header='';if(item.weekId!==currentWeek){currentWeek=item.weekId;const w=weeks.find(x=>x.id===currentWeek);if(w)header=readingWeekHeader(w);}return header+lessonMarkup(item);}).join(''); $('#reading').innerHTML=`<div class="reading-inner"><h1>${esc(c?displayCourseTitle(c):'복습')}</h1><p class="intro">주차 순서대로 읽으며 필요한 곳에서 바로 질문할 수 있습니다.</p>${body||'<p class="muted">아직 읽을 카드가 없습니다.</p>'}<div class="quiz-finish"><button class="primary" id="finishQuiz">오늘 공부 퀴즈</button></div></div>`;
  $$('[data-preview-week]',$('#reading')).forEach(button=>button.addEventListener('click',()=>{const w=weeks.find(x=>x.id===button.dataset.previewWeek);cards.filter(item=>item.weekId===w?.id).forEach(item=>exposure('preview',item.id));showTextDialog('대표 풀이',w?.preview?.solution||'');})); bindLessonActions($('#reading')); $('#finishQuiz').onclick=()=>setView('quiz'); restoreChat().catch(showError); restoreReading(); requestAnimationFrame(()=>{exposeVisible();buildReadingRail();});
}
function restoreReading(){ const y=state.readingPositions[scopeKey()] ?? 0; if(Number.isFinite(y))$('#reading').scrollTo({top:y,behavior:'instant'}); }
function jumpTo(id){ state.cardId=id;if(reviewCandidate&&document.querySelector('#reading').dataset.loading==='true'){state.pendingReviewCard=id;return;} (reviewCandidate?($('#source-'+CSS.escape(id))||$('#lesson-'+CSS.escape(id))):$('#lesson-'+CSS.escape(id)))?.scrollIntoView({behavior:'instant',block:'start'}); updateRailLabel(id); renderChatContext(); $$('.outline-button').forEach(x=>x.classList.toggle('selected',x.dataset.jump===id)); saveUi(); }
function exposure(kind, cardId){ if(reviewPreview||!state.courseId)return; request('/exposure',{method:'POST',body:JSON.stringify({courseId:state.courseId,cardId,kind,requestId:uuid()})}).catch(()=>{}); }
function exposeVisible(){ const point=$('#reading').getBoundingClientRect().top+140; const here=$$('.lesson').find(x=>{const r=x.getBoundingClientRect();return r.top<=point&&r.bottom>point;}); const visible=here||$$('.lesson').find(x=>{const r=x.getBoundingClientRect();return r.bottom>point&&r.top<$('#reading').getBoundingClientRect().bottom;});if(visible){state.cardId=visible.dataset.card;exposure('read',state.cardId);updateRailLabel(state.cardId);renderChatContext();} }
function chatWeek(){return card()?.weekId||(reviewCandidate?state.reviewWeekId:null)||state.weekId||course()?.weeks?.[0]?.id;}
function chatDraftKey(){return reviewCandidate?`${state.courseId}/${chatWeek()||''}`:scopeKey();}
function renderChatContext(){ const c=card(); $('#chatContext').textContent=state.selection ? `선택한 문장: ${state.selection}` : (c ? `${c.title} · 현재 읽는 내용` : (reviewCandidate?'질문할 개념을 왼쪽 목차에서 선택하세요.':'현재 읽는 범위')); }
async function restoreChat(){ const log=$('#chatLog'), token=++state.chatLoad, courseId=state.courseId, weekId=chatWeek(), key=chatDraftKey(); log.innerHTML='<p class="chat-empty">읽다가 막힌 한 문장이나 연결을 물어보세요. 답변은 현재 읽는 개념 안에서 이어집니다.</p>'; $('#chatInput').value=state.drafts[key] || ''; renderChatContext(); try { const r=await request(`/chats?courseId=${encodeURIComponent(courseId)}&weekId=${encodeURIComponent(weekId)}`); if(token!==state.chatLoad || courseId!==state.courseId || weekId!==chatWeek())return; if(r.messages?.length){log.innerHTML=''; r.messages.forEach(message); log.scrollTop=log.scrollHeight;} } catch(e){if(token===state.chatLoad)log.innerHTML=`<p class="chat-empty">대화를 불러오지 못했습니다. 새 질문은 초안으로 보관됩니다.</p>`;} }
function message(m){ const log=$('#chatLog'); $('.chat-empty',log)?.remove(); log.insertAdjacentHTML('beforeend',`<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?'<span class="label">도움말</span>':''}${inlineMarkdown(m.text)}</div>`); if(m.proposal) proposal(m.proposal); }
function proposal(p){ const original=card(p.cardId), changes=[]; for(const [key,value] of Object.entries(p.patch||{})){if(key==='details'){const before=new Map((original?.details||[]).map(d=>[d.id,d]));for(const d of value){const old=before.get(d.id);if(!old)changes.push(`+ ${d.title}: ${d.text}`);else if(old.text!==d.text||old.title!==d.title)changes.push(`~ ${old.title}: ${old.text}\n  → ${d.title}: ${d.text}`);}for(const old of before.values())if(!value.some(d=>d.id===old.id))changes.push(`− ${old.title}: ${old.text}`);}else changes.push(`~ ${key}\n  ${String(original?.[key]||'(없음)')}\n  → ${String(value)}`);} const log=$('#chatLog'); log.insertAdjacentHTML('beforeend',`<div class="proposal"><strong>카드에 반영할 제안</strong><p>${esc(p.reason || '설명을 보완합니다.')}</p><details><summary>바뀌는 내용 보기</summary><p style="white-space:pre-wrap">${esc(changes.join('\n\n') || '변경 내용을 확인할 수 없습니다.')}</p></details><button class="primary" data-approve="${esc(p.cardId)}">반영</button><button class="quiet" data-dismiss>보류</button></div>`); const box=log.lastElementChild; $('[data-dismiss]',box).onclick=()=>box.remove(); $('[data-approve]',box).onclick=()=>approveProposal(p,box); }
async function approveProposal(p, box){ try{ const updated=await request(`/cards/${encodeURIComponent(p.cardId)}`,{method:'POST',body:JSON.stringify({version:p.version,patch:p.patch,reason:p.reason,requestId:uuid()})}); const index=state.data.cards.findIndex(c=>c.id===updated.id);state.data.cards[index]=updated; box.innerHTML='<strong>카드에 반영했습니다.</strong><p>읽는 문서와 보드에 같은 내용이 반영됩니다.</p><button>되돌리기</button>'; $('button',box).onclick=()=>undoCard(updated,box); refreshCurrentCard(updated.id); toast('카드 내용을 저장했습니다.'); }catch(e){showError(e);} }
async function undoCard(c, box){try{const updated=await request(`/cards/${encodeURIComponent(c.id)}/undo`,{method:'POST',body:JSON.stringify({version:c.version,requestId:uuid()})});state.data.cards[state.data.cards.findIndex(x=>x.id===c.id)]=updated;box.remove();refreshCurrentCard(c.id);toast('카드 변경을 되돌렸습니다.');}catch(e){showError(e);}}
function refreshCurrentCard(id){if(state.view!=='review')return;if(reviewCandidate){saveUi();renderReview();return;}const old=$(`#lesson-${CSS.escape(id)}`), next=card(id);if(!old||!next)return;old.outerHTML=lessonMarkup(next);bindLessonActions($(`#lesson-${CSS.escape(id)}`));}
async function sendChat(event){event.preventDefault(); const input=$('#chatInput'), question=input.value.trim(), key=chatDraftKey(),current=card(); if(!question)return; if(reviewCandidate&&!current){toast('왼쪽 목차에서 질문할 개념을 선택해주세요.');return;} state.drafts[key]=question; saveUi(); $('#draftState').textContent='보내는 중…'; $('#chatSend').disabled=true; message({role:'user',text:question}); try { const result=await request('/chat',{method:'POST',body:JSON.stringify({courseId:state.courseId,weekId:current?.weekId||state.weekId,cardId:state.cardId,cardVersion:current?.version,selection:state.selection,question,requestId:uuid()})}); const answer=await poll(result.jobId); delete state.drafts[key]; input.value='';$('#draftState').textContent=''; saveUi(); message({role:'assistant',text:answer.answer,proposal:answer.proposal}); } catch(e){ $('#draftState').textContent='초안이 남아 있습니다'; input.value=state.drafts[key] || question; inlineError(e); } finally {$('#chatSend').disabled=false;} }
async function poll(jobId){ const controller={cancelled:false}; state.polling.set(jobId,controller); const started=Date.now(); try{while(!controller.cancelled){ const j=await request(`/jobs/${encodeURIComponent(jobId)}`); if(j.status==='done')return j.result; if(j.status==='error')throw new Error(j.error || '응답을 만들지 못했습니다.'); if(j.status==='cancelled')throw new Error('요청을 취소했습니다.'); showWorking(jobId,jobWaitText(j,Date.now()-started)); await new Promise(r=>setTimeout(r,700)); } throw new Error('요청을 취소했습니다.');}finally{state.polling.delete(jobId);const box=$('#jobCancel');if(box?.dataset.jobId===jobId)box.remove();} }
function showWorking(jobId,message){const pending=state.data?.pendingJobs?.find(j=>j.id===jobId);if(pending?.kind==='quiz'&&(state.view!=='quiz'||pending.courseId!==state.courseId))return;let host=state.view==='quiz'?$('#quizPage'):($('#dialog').open?$('#dialog'):$('#chatLog'));if(!host)return;let box=$('#jobCancel');if(box&&box.dataset.jobId!==jobId)box.remove();if(!box||box.dataset.jobId!==jobId){host.insertAdjacentHTML('beforeend',`<div class="message" id="jobCancel" data-job-id="${esc(jobId)}"><span class="label">진행 중</span><span class="job-message"></span> <button class="quiet">취소</button></div>`);box=$('#jobCancel');$('button',box).onclick=async()=>{try{await request(`/jobs/${jobId}/cancel`,{method:'POST',body:JSON.stringify({})});}catch(e){showError(e);}};}$('.job-message',box).textContent=message;}

function activeQuestion(){ return state.quiz?.questions?.[state.quizIndex ?? 0]; }
function quizDraftKey(q){return `${state.quiz?.id||'new'}/${q.id}`;}
function cacheAnswer(q){const field=$('#answerText');if(field){state.quizDrafts[quizDraftKey(q)]={text:field.value,assetId:state.asset?.id};saveUi();}}
function renderQuestion(){if(reviewCandidate)return mountQuizSheet({$,esc,state,api,request,poll,uuid,saveUi,refreshCatalog,inlineError,showTextDialog,feedbackMarkup,bindFeedback,finishQuiz,pauseQuiz,inlineMarkdown,setView}); const quiz=state.quiz,q=activeQuestion(); if(!quiz||!q)return quizSetupToday(); const answer=quiz.answers?.[q.id]||{}, local=state.quizDrafts[quizDraftKey(q)]||{}; state.asset=(local.assetId||answer.assetId)?{id:local.assetId||answer.assetId}:null; const position=(state.quizIndex||0)+1; const pending=quiz.questions.filter(x=>!quiz.answers?.[x.id]?.submitted).length; $('#quizPage').innerHTML=`<div class="quiz-inner"><div class="question-meta"><span>오늘 공부 퀴즈 · ${position} / ${quiz.questions.length}</span><span><button class="quiet" id="pauseQuiz">나중에 이어가기</button><button class="quiet" id="finishEarly">묶음 마치기</button></span></div><section class="question"><h2>${esc(q.title)}</h2><p>${inlineMarkdown(q.prompt)}</p><textarea class="answer" id="answerText" placeholder="풀이와 생각을 적으세요.">${esc(local.text??answer.text??'')}</textarea><div class="asset-preview" id="assetPreview">${state.asset?.id?'<span>첨부한 풀이 사진이 있습니다.</span>':''}</div><div class="quiz-actions"><div><input hidden id="assetInput" type="file" accept="image/*"><button id="addAsset">풀이 사진</button><button class="quiet" id="hint">도움 보기</button></div><button class="primary" id="submitAnswer">제출</button></div><p class="assist-note" id="assistNote"></p><div id="feedback"></div><div class="dialog-actions"><button id="previousQuestion" ${position===1?'disabled':''}>이전 문제</button><button id="nextQuestion" ${position===quiz.questions.length?'disabled':''}>다음 문제</button></div></section></div>`; $('#pauseQuiz').onclick=()=>{cacheAnswer(q);pauseQuiz();}; $('#finishEarly').onclick=()=>{cacheAnswer(q);if(pending&& !confirm(`아직 ${pending}문항을 제출하지 않았습니다. 지금 묶음을 마칠까요?`))return;finishQuiz();}; $('#addAsset').onclick=()=>$('#assetInput').click(); $('#assetInput').onchange=uploadAsset; $('#hint').onclick=()=>askHint(q); $('#submitAnswer').onclick=()=>submitAnswer(q); $('#answerText').oninput=()=>cacheAnswer(q); $('#previousQuestion').onclick=()=>{cacheAnswer(q);state.quizIndex--;renderQuestion();};$('#nextQuestion').onclick=()=>{cacheAnswer(q);state.quizIndex++;renderQuestion();}; if(answer.assisted)$('#assistNote').textContent='도움을 본 뒤의 답안은 도움 전 답안과 구분해 기록합니다.'; if(answer.feedback) renderFeedback(answer.feedback); }
async function uploadAsset(event){ const f=event.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>8*1024*1024){toast('8MB 이하의 이미지 파일을 선택해주세요.');return;} const reader=new FileReader(); reader.onload=async()=>{try{const r=await request('/assets',{method:'POST',body:JSON.stringify({name:f.name,mime:f.type,data:reader.result.split(',')[1]})});state.asset={...r,url:activeUrl(r.url)};cacheAnswer(activeQuestion());$('#assetPreview').innerHTML=`<img src="${esc(state.asset.url)}" alt="첨부한 풀이 사진"><span>${esc(f.name)}</span>`;}catch(e){inlineError(e);}};reader.readAsDataURL(f); }
function answerPayload(q){return {questionId:q.id,text:$('#answerText').value,assetId:state.asset?.id,comment:'',requestId:uuid()};}
async function askHint(q){ const trigger=$('#hint');try{trigger.disabled=true;const r=await request(`/quiz/${encodeURIComponent(state.quiz.id)}/hint`,{method:'POST',body:JSON.stringify(answerPayload(q))});const result=await poll(r.jobId);state.quiz=result.quiz;state.data.activeQuiz=result.quiz;await refreshCatalog();$('#assistNote').textContent='도움을 본 뒤의 답안은 도움 전 답안과 구분해 기록합니다.';showTextDialog('도움',result.hint);}catch(e){inlineError(e);}finally{if(trigger)trigger.disabled=false;} }
async function submitAnswer(q){ const trigger=$('#submitAnswer');try{trigger.disabled=true;cacheAnswer(q);const r=await request(`/quiz/${encodeURIComponent(state.quiz.id)}/answer`,{method:'POST',body:JSON.stringify(answerPayload(q))});const result=await poll(r.jobId);delete state.quizDrafts[quizDraftKey(q)];saveUi();state.quiz=result.quiz;state.data.activeQuiz=result.quiz;await refreshCatalog();if(result.feedback)renderFeedback(result.feedback);else renderQuestion();}catch(e){inlineError(e);if(trigger)trigger.disabled=false;} }
function feedbackMarkup(f,{controls=false}={}){return `<div class="feedback" data-feedback="${esc(f.questionId)}">${rubricMarkup(f)}<h3>확인된 것</h3><p>${inlineMarkdown(f.confirmed||'')}</p><details class="review-request"><summary>판독·채점 다시 확인</summary><p class="muted">제출한 원답은 그대로 두고, 판독 또는 채점 근거만 다시 확인합니다.</p><input aria-label="재확인 이유" placeholder="예: 사진의 부호가 잘못 읽힌 것 같아요"><button class="quiet" data-request-review="${esc(f.questionId)}">재확인 요청</button></details>${controls?'<div class="dialog-actions"><button data-review-card>이 설명 다시 읽기</button><button data-back-edit>답안 고치기</button><button class="primary" data-continue></button></div>':''}</div>`;}
function bindFeedback(box,f,{controls=false}={}){ $('[data-request-review]',box)?.addEventListener('click',()=>requestReview(f,$('[data-request-review]',box))); if(!controls)return; $('[data-review-card]',box).textContent=f.reviewCardId?'이 설명 다시 읽기':'읽는 화면으로'; $('[data-review-card]',box).onclick=()=>{state.cardId=f.reviewCardId||activeQuestion()?.cardId;setView('review');setTimeout(()=>jumpTo(state.cardId),20);}; $('[data-back-edit]',box).onclick=()=>$('#answerText').focus(); const last=(state.quizIndex||0)===state.quiz.questions.length-1; $('[data-continue]',box).textContent=last?'묶음 마치기':'다음 문제'; $('[data-continue]',box).onclick=()=>{if(last)finishQuiz();else{state.quizIndex++;renderQuestion();}};}
function renderFeedback(f){ const host=$('#feedback');host.innerHTML=feedbackMarkup(f,{controls:true});bindFeedback($('.feedback',host),f,{controls:true}); }
async function requestReview(feedback,button){const box=button.closest('.feedback'),input=$('input',box),reason=input.value.trim();if(!reason){input.focus();return;}button.disabled=true;button.textContent='재확인 중…';try{const r=await request(`/quiz/${encodeURIComponent(state.quiz.id)}/review`,{method:'POST',body:JSON.stringify({questionId:feedback.questionId,reason,requestId:uuid()})});const result=await poll(r.jobId);state.quiz=result.quiz;state.data.activeQuiz=result.quiz?.status==='active'?result.quiz:null;await refreshCatalog();const updated=result.feedback;box.outerHTML=feedbackMarkup(updated,{controls:box.closest('#feedback')!==null});const next=$(`[data-feedback="${CSS.escape(updated.questionId)}"]`);bindFeedback(next,updated,{controls:next.closest('#feedback')!==null});toast('제출한 원답을 기준으로 근거를 다시 확인했습니다.');}catch(e){button.disabled=false;button.textContent='재확인 요청';inlineError(e);}}
function savedAnswerMarkup(quiz,f){const q=(quiz.questions||[]).find(x=>x.id===f.questionId),a=quiz.answers?.[f.questionId];if(!q||!a)return '';return `<details class="saved-answer"><summary>문제·내 답안 보기</summary><h3>${esc(q.title)}</h3><p style="white-space:pre-wrap">${inlineMarkdown(q.prompt)}</p><p style="white-space:pre-wrap">${esc(a.text||'사진으로 제출한 답안입니다.')}</p>${a.assetId?`<img style="max-width:100%;max-height:460px;object-fit:contain" src="${api}/assets/${encodeURIComponent(a.assetId)}" alt="저장한 원본 답안">`:''}</details>`;}
function renderFinishedQuiz(quiz, summary=quiz.summary, feedbacks=quiz.feedback||[]){const resultSummary=summary||{};$('#quizPage').innerHTML=`<div class="quiz-inner"><h1>묶음을 마쳤습니다.</h1><p>${esc(resultSummary.nextAction || '다음 학습으로 이어가세요.')}</p><p class="muted">수업 목표 확인 ${esc(resultSummary.confirmed||0)} / ${esc(resultSummary.total||0)} · 이번 묶음 미제출 ${esc(resultSummary.pending||0)}문항</p><p class="muted">한 번의 정답만으로 목표 달성을 확정하지 않습니다. 확인된 풀이와 남은 내용은 함께 보관됩니다.</p><div id="finishedFeedback">${feedbacks.map(f=>savedAnswerMarkup(quiz,f)+feedbackMarkup(f)).join('')}</div><div class="dialog-actions"><button id="finishBack">보드로</button><button class="primary" id="finishedRecords">기록 및 관리</button></div></div>`;$$('#finishedFeedback .feedback').forEach((box,index)=>bindFeedback(box,feedbacks[index]));$('#finishBack').onclick=()=>setView('board');$('#finishedRecords').onclick=()=>setView('history');}
async function finishQuiz(){const triggers=[$('#finishEarly'),$('#continueQuiz')].filter(Boolean);try{triggers.forEach(x=>x.disabled=true);const r=await request(`/quiz/${encodeURIComponent(state.quiz.id)}/finish`,{method:'POST',body:JSON.stringify({requestId:uuid()})});const result=await poll(r.jobId);state.quiz=result.quiz;state.data.activeQuiz=null;await refreshCatalog();renderFinishedQuiz(result.quiz,result.summary,result.feedback||result.quiz?.feedback||[]);}catch(e){triggers.forEach(x=>x.disabled=false);inlineError(e);}}
async function pauseQuiz(){try{await request(`/quiz/${encodeURIComponent(state.quiz.id)}/pause`,{method:'POST',body:JSON.stringify({requestId:uuid()})});toast('여기까지 저장했습니다. 다음에 이어서 풀 수 있습니다.');setView('review');}catch(e){showError(e);}}

function editCard(id){const c=card(id);const d=$('#dialog');if(d.open)d.close();d.innerHTML=`<h2>${esc(c.title)} 수정</h2><p class="muted">이유를 남기면 이전 내용과 비교할 수 있습니다.</p><textarea class="editor" id="editCore">${esc(c.core)}</textarea><input id="editReason" placeholder="수정 이유 (선택)" style="width:100%;margin-top:10px;padding:8px;border:1px solid #dfe4e1;border-radius:7px"><div class="dialog-actions"><button id="cancelEdit">취소</button><button class="primary" id="saveEdit">저장</button></div>`;d.showModal();$('#cancelEdit').onclick=()=>d.close();$('#saveEdit').onclick=async()=>{try{const updated=await request(`/cards/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({version:c.version,patch:{core:$('#editCore').value},reason:$('#editReason').value,requestId:uuid()})});state.data.cards[state.data.cards.findIndex(x=>x.id===id)]=updated;d.close();render();toast('카드를 저장했습니다.');}catch(e){showError(e);}};}
async function showHistory(id){try{const r=await request(`/history?courseId=${encodeURIComponent(state.courseId)}`);const c=card(id), states=c.requirementStates||{};const sourceUrl=`${api}/source?cardId=${encodeURIComponent(id)}`;const reqs=(c.requirements||[]).map(req=>{const s=states[req.id]||{};const review=s.retention?.nextReviewAt?` · 다음 확인 ${new Date(s.retention.nextReviewAt).toLocaleDateString('ko-KR')}`:'';return `<li><strong>${esc(req.behavior)}</strong><br><span class="muted">${esc(s.confirmed ? '목표 확인' : s.observed ? '학습 중' : '미평가')}${esc(s.retention?.label ? ` · ${s.retention.label}` : '')}${esc(review)}</span></li>`;}).join('');const relevant=(r.events||[]).filter(e=>!e.cardId||e.cardId===id);const selected=[...relevant.filter(e=>e.quizId).slice(0,8),...relevant.filter(e=>!e.quizId).slice(0,6)];const events=selected.map(e=>`<li>${esc(`${e.createdAt ? new Date(e.createdAt).toLocaleString('ko-KR') : ''} ${e.summary || ({card_edited:'설명 보완',evidence_invalidated:'변경된 내용의 평가 근거 재검토',attempt_corrected:'이전 판정 정정'})[e.type] || '학습 기록'}`)}${e.quizId?` <button class="quiet" data-open-quiz="${esc(e.quizId)}">이 풀이 다시 보기</button>`:''}</li>`).join('')||'<li>아직 확인할 기록이 없습니다.</li>';const d=$('#dialog');d.innerHTML=`<button class="quiet close" aria-label="닫기">×</button><h2>출처·기록</h2><p><a href="${sourceUrl}" target="_blank" rel="noopener">${esc(c.source?.label || '출처 정보')}</a>${c.source?.locator?`<br><span class="muted">${esc(c.source.locator)}</span>`:''}</p>${reqs?`<ul>${reqs}</ul>`:''}<ul>${events}</ul><div class="dialog-actions"><button class="primary">닫기</button></div>`;d.showModal();$('.close',d).onclick=()=>d.close();$('.primary',d).onclick=()=>d.close();$$('[data-open-quiz]',d).forEach(b=>b.onclick=()=>openFinishedQuiz(b.dataset.openQuiz));}catch(e){showError(e);}}
async function openFinishedQuiz(id){try{const quiz=await request(`/quiz/${encodeURIComponent(id)}`);$('#dialog').close();state.quiz=quiz;setView('quiz');renderFinishedQuiz(quiz,quiz.summary,quiz.feedback||[]);}catch(e){showError(e);}}
function showTextDialog(title,text){const d=$('#dialog');d.innerHTML=`<button class="quiet close" aria-label="닫기">×</button><h2>${esc(title)}</h2><p style="white-space:pre-wrap">${esc(text)}</p><div class="dialog-actions"><button class="primary">닫기</button></div>`;d.showModal();$('.close',d).onclick=()=>d.close();$('.primary',d).onclick=()=>d.close();}
function openImport(){return openMaterialsImport({$,esc,state,api,request,poll,uuid,toast,bootstrap,showError,showWorking});}
function renderMaterials(){return mountMaterials({$,esc,state,api,request,course:course(),openImport,openCourseManager:()=>openCourseManager({state,request,uuid,bootstrap,toast}),showError});}
async function importMaterial(){const file=$('#importFile').files[0];let fileData;if(file){if(file.size>20*1024*1024){toast('20MB 이하 파일을 선택해주세요.');return;}fileData=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result.split(',')[1]);r.onerror=no;r.readAsDataURL(file);});}try{const r=await request('/import',{method:'POST',body:JSON.stringify({courseTitle:$('#importCourse').value,weekTitle:$('#importWeek').value,title:$('#importTitle').value,text:$('#importText').value, ...(file?{fileName:file.name,fileData}:{}),requestId:uuid()})});$('#dialog').close();toast('자료를 읽을 준비를 하고 있습니다.');await poll(r.jobId);await bootstrap();}catch(e){showError(e);}}
function showError(error){toast(error.message || '처리하지 못했습니다.');}
function inlineError(error){const host=state.view==='quiz'?$('#quizPage'):($('#dialog').open?$('#dialog'):$('#chatLog'));if(host){let box=$('#inlineError');if(!box){host.insertAdjacentHTML('beforeend','<p class="message" id="inlineError"></p>');box=$('#inlineError');}box.textContent=error.message || '처리하지 못했습니다.';}showError(error);}
function openChat(){panels.openChat();}
function setView(view){state.view=view;location.hash=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id===`${view}View`));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));render();saveUi();}
function render(){if(!state.data)return;document.body.classList.toggle('study-shell',reviewCandidate);document.body.classList.toggle('review-candidate',reviewCandidate&&state.view==='review');renderSidebar();if(state.view==='board'){renderBoard();}else if(state.view==='review'){renderReview();}else if(state.view==='materials')renderMaterials();else if(state.view==='history')mountManagement({state,request,api,saveUi,uuid,setView,poll,refreshCatalog});else quizSetupToday();}
async function resumePendingJobs(){
  const jobs=(state.data?.pendingJobs||[]).filter(j=>j.kind==='quiz'&&['queued','running','pending'].includes(j.status)&&!state.resumedJobs.has(j.id));
  for(const job of jobs){
    state.resumedJobs.add(job.id);
    poll(job.id).then(result=>{
      state.data.pendingJobs=(state.data.pendingJobs||[]).filter(j=>j.id!==job.id);
      if(result?.questions)state.data.activeQuiz=result;
      if(job.courseId!==state.courseId||state.view!=='quiz'){toast('퀴즈가 준비되었습니다. 퀴즈 화면에서 이어서 풀 수 있습니다.');return;}
      if(result?.needsReview){state.cardId=result.cardId;setView('review');setTimeout(()=>jumpTo(result.cardId),20);toast(result.message||'설명을 다시 읽고 확인해보세요.');return;}
      if(result?.questions){state.quiz=result;state.quizIndex=0;state.asset=null;renderQuestion();}
    }).catch(async error=>{
      state.data.pendingJobs=(state.data.pendingJobs||[]).filter(j=>j.id!==job.id);
      if(job.courseId===state.courseId&&state.view==='quiz'){await quizSetupToday();inlineError(error);}else toast(error.message);
    });
  }
}
