function updateRailLabel(cardId){const rail=$('#readingRail'),item=card(cardId),w=course()?.weeks?.find(x=>x.id===item?.weekId);if(!rail)return;const text=[w?weekLabel(w):'',item?.title].filter(Boolean).join(' · ')||'읽는 위치';const label=$('.rail-current',rail);if(label)label.textContent=text;$('#reviewScope').textContent=text;$('#reviewScope').title=text;$$('.rail-dot',rail).forEach(dot=>dot.classList.toggle('active',dot.dataset.rail===cardId));}
function buildReadingRail(){let rail=$('#readingRail');if(!rail){rail=document.createElement('aside');rail.id='readingRail';rail.className='reading-rail';rail.setAttribute('aria-label','읽기 위치');$('#chat').before(rail);}const lessons=$$('.lesson');rail.innerHTML=`<p class="rail-current" aria-live="polite"></p><div class="rail-dots">${lessons.map((x,i)=>{const item=card(x.dataset.card),w=course()?.weeks?.find(v=>v.id===item?.weekId);const title=[w?weekLabel(w):'',x.querySelector('h2')?.textContent||`개념 ${i+1}`].filter(Boolean).join(' · ');return `<button class="rail-dot ${x.dataset.card===state.cardId?'active':''}" data-rail="${esc(x.dataset.card)}" aria-label="${esc(title)}" title="${esc(title)}"></button>`;}).join('')}</div>`;$$('[data-rail]',rail).forEach(b=>b.onclick=()=>jumpTo(b.dataset.rail));updateRailLabel(state.cardId);if(state.railObserver)state.railObserver.disconnect();state.railObserver=new IntersectionObserver(entries=>{const hit=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(hit){const changed=state.cardId!==hit.target.dataset.card;state.cardId=hit.target.dataset.card;if(changed)exposure('read',state.cardId);updateRailLabel(state.cardId);renderChatContext();}}, {root:$('#reading'),rootMargin:'-18% 0px -66% 0px',threshold:[.05,.3]});lessons.forEach(x=>state.railObserver.observe(x));}
